     1→/**
     2→ * FreeWire - 백엔드 API 서버
     3→ * POST /compile  → 그래프 JSON → .free 코드
     4→ * POST /execute  → 그래프 JSON → HTML/CSS/JS
     5→ * GET  /preview/:id → 브라우저 미리보기
     6→ * GET  /health
     7→ */
     8→
     9→const http = require('http');
    10→const { Graph }          = require('../core/graph');
    11→const { GraphCompiler }  = require('../compiler/graph-compiler');
    12→const { FreeExecutor }   = require('./free-executor');
    13→const { aiGenerateGraph } = require('./ai-graph-generator');
    14→
    15→const PORT = process.env.FREEWIRE_PORT || 4010;
    16→
    17→const compiler = new GraphCompiler();
    18→const executor = new FreeExecutor();
    19→
    20→// 미리보기 캐시 { id → { html, css, js, createdAt } }
    21→const previewCache = new Map();
    22→
    23→// ─── 라우터 ─────────────────────────────────────────────────────
    24→const ROUTES = {
    25→  'GET /health':       handleHealth,
    26→  'GET /api/nodes':    handleNodeTypes,
    27→  'POST /api/compile': handleCompile,
    28→  'POST /api/execute': handleExecute,
    29→  'POST /api/preview': handlePreviewCreate,
    30→  'POST /api/ai-generate': handleAIGenerate,
    31→};
    32→
    33→function router(req, res) {
    34→  const key = `${req.method} ${req.url.split('?')[0]}`;
    35→
    36→  // GET /preview/:id
    37→  if (req.method === 'GET' && req.url.startsWith('/preview/')) {
    38→    return handlePreviewGet(req, res);
    39→  }
    40→
    41→  const handler = ROUTES[key];
    42→  if (handler) return handler(req, res);
    43→
    44→  send(res, 404, { error: `라우트 없음: ${key}` });
    45→}
    46→
    47→// ─── 핸들러 ─────────────────────────────────────────────────────
    48→
    49→function handleHealth(req, res) {
    50→  send(res, 200, {
    51→    status: 'ok',
    52→    service: 'FreeWire API',
    53→    version: '0.1.0',
    54→    uptime: process.uptime().toFixed(1) + 's',
    55→  });
    56→}
    57→
    58→function handleNodeTypes(req, res) {
    59→  const { NODE_TYPE_DEFS } = require('../core/node-types-index');
    60→  send(res, 200, { nodeTypes: NODE_TYPE_DEFS });
    61→}
    62→
    63→async function handleCompile(req, res) {
    64→  let body;
    65→  try { body = await readBody(req); }
    66→  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }
    67→
    68→  const { graph } = body;
    69→  if (!graph) return send(res, 400, { error: 'body.graph 필수' });
    70→
    71→  try {
    72→    const result = compiler.compile(graph);
    73→    send(res, 200, {
    74→      code:     result.code,
    75→      errors:   result.errors,
    76→      warnings: result.warnings,
    77→    });
    78→  } catch (e) {
    79→    send(res, 500, { error: '컴파일 실패: ' + e.message });
    80→  }
    81→}
    82→
    83→async function handleExecute(req, res) {
    84→  let body;
    85→  try { body = await readBody(req); }
    86→  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }
    87→
    88→  const { graph } = body;
    89→  if (!graph) return send(res, 400, { error: 'body.graph 필수' });
    90→
    91→  try {
    92→    const compiled = compiler.compile(graph);
    93→    if (compiled.errors.length > 0) {
    94→      return send(res, 422, { error: '컴파일 오류', details: compiled.errors });
    95→    }
    96→    const output = executor.execute(compiled.code, graph);
    97→    send(res, 200, output);
    98→  } catch (e) {
    99→    send(res, 500, { error: '실행 실패: ' + e.message });
   100→  }
   101→}
   102→
   103→async function handlePreviewCreate(req, res) {
   104→  let body;
   105→  try { body = await readBody(req); }
   106→  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }
   107→
   108→  const { graph } = body;
   109→  if (!graph) return send(res, 400, { error: 'body.graph 필수' });
   110→
   111→  try {
   112→    const compiled = compiler.compile(graph);
   113→    if (compiled.errors.length > 0) {
   114→      return send(res, 422, { error: '컴파일 오류', details: compiled.errors });
   115→    }
   116→    const output = executor.execute(compiled.code, graph);
   117→    const id     = `preview-${Date.now()}`;
   118→
   119→    // 캐시 최대 100개 제한 (LRU: 가장 오래된 항목 제거)
   120→    if (previewCache.size >= 100) {
   121→      const oldest = previewCache.keys().next().value;
   122→      previewCache.delete(oldest);
   123→    }
   124→    previewCache.set(id, { ...output, createdAt: Date.now() });
   125→
   126→    // 캐시 1시간 TTL
   127→    setTimeout(() => previewCache.delete(id), 3600_000);
   128→
   129→    send(res, 201, { previewId: id, url: `/preview/${id}` });
   130→  } catch (e) {
   131→    send(res, 500, { error: '미리보기 생성 실패: ' + e.message });
   132→  }
   133→}
   134→
   135→
   136→async function handleAIGenerate(req, res) {
   137→  let body;
   138→  try { body = await readBody(req); }
   139→  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }
   140→
   141→  const { prompt, apiKey } = body;
   142→  if (!prompt) return send(res, 400, { error: 'body.prompt 필수' });
   143→
   144→  try {
   145→    const result = await aiGenerateGraph(prompt, apiKey);
   146→    send(res, 200, result);
   147→  } catch (e) {
   148→    send(res, 500, { error: 'AI 생성 실패: ' + e.message });
   149→  }
   150→}
   151→
   152→function handlePreviewGet(req, res) {
   153→  const id = req.url.replace('/preview/', '').split('?')[0];
   154→  const preview = previewCache.get(id);
   155→
   156→  if (!preview) {
   157→    res.writeHead(404, { 'Content-Type': 'text/html' });
   158→    res.end('<h1>미리보기 없음 (만료되었거나 잘못된 ID)</h1>');
   159→    return;
   160→  }
   161→
   162→  const html = buildPreviewHtml(preview);
   163→  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
   164→  res.end(html);
   165→}
   166→
   167→// ─── 유틸 ────────────────────────────────────────────────────────
   168→
   169→function buildPreviewHtml({ html, css, js }) {
   170→  return `<!DOCTYPE html>
   171→<html lang="ko">
   172→<head>
   173→  <meta charset="UTF-8">
   174→  <meta name="viewport" content="width=device-width, initial-scale=1.0">
   175→  <title>FreeWire 미리보기</title>
   176→  <style>
   177→    * { box-sizing: border-box; margin: 0; padding: 0; }
   178→    body { font-family: system-ui, sans-serif; padding: 24px; background: #f9fafb; }
   179→    .freewire-badge {
   180→      position: fixed; bottom: 12px; right: 12px;
   181→      background: #6366f1; color: white;
   182→      padding: 4px 10px; border-radius: 999px;
   183→      font-size: 12px; opacity: 0.85;
   184→    }
   185→    ${css || ''}
   186→  </style>
   187→</head>
   188→<body>
   189→  <div id="app">${html || '<p style="color:#999">내용 없음</p>'}</div>
   190→  <div class="freewire-badge">⚡ FreeWire</div>
   191→  <script>${js || ''}</script>
   192→</body>
   193→</html>`;
   194→}
   195→
   196→function send(res, status, data) {
   197→  const body = JSON.stringify(data);
   198→  res.writeHead(status, {
   199→    'Content-Type':  'application/json',
   200→    'Access-Control-Allow-Origin': '*',
   201→    'Access-Control-Allow-Headers': 'Content-Type',
   202→  });
   203→  res.end(body);
   204→}
   205→
   206→function readBody(req) {
   207→  return new Promise((resolve, reject) => {
   208→    let data = '';
   209→    req.on('data', chunk => { data += chunk; if (data.length > 1_000_000) reject(new Error('너무 큰 요청')); });
   210→    req.on('end',  () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
   211→    req.on('error', reject);
   212→  });
   213→}
   214→
   215→// ─── 서버 시작 ───────────────────────────────────────────────────
   216→const server = http.createServer((req, res) => {
   217→  if (req.method === 'OPTIONS') {
   218→    res.writeHead(204, { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'Content-Type', 'Access-Control-Allow-Methods': 'GET,POST' });
   219→    return res.end();
   220→  }
   221→  router(req, res);
   222→});
   223→
   224→if (require.main === module) {
   225→  server.listen(PORT, () => {
   226→    console.log(`\n⚡ FreeWire API 서버 시작`);
   227→    console.log(`   http://localhost:${PORT}/health`);
   228→    console.log(`   POST http://localhost:${PORT}/api/compile`);
   229→    console.log(`   POST http://localhost:${PORT}/api/execute`);
   230→    console.log(`   POST http://localhost:${PORT}/api/preview\n`);
   231→  });
   232→}
   233→
   234→module.exports = { server, previewCache };
   235→

