     1→/**
     2→ * FreeWire Phase 5 - AI 노드 자동 생성기
     3→ *
     4→ * 텍스트 한 줄 → 노드 그래프 JSON 자동 생성
     5→ *
     6→ * 동작 방식:
     7→ *   1. IntentParser: 자연어 → 의도 파악 (키워드 + 패턴)
     8→ *   2. TemplateEngine: 의도 → 노드 배치 계획
     9→ *   3. LayoutEngine: 노드 위치 자동 계산 (겹침 방지)
    10→ *   4. (선택) LLM 브릿지: 로컬 서버 or Claude API 연동
    11→ */
    12→
    13→'use strict';
    14→
    15→// ─── 노드 팩토리 ─────────────────────────────────────────────────
    16→
    17→const uid = () => `ai-${Date.now()}-${Math.floor(Math.random() * 1000000)}`;
    18→
    19→const NODE = {
    20→  button: (label = '버튼', variant = 'primary') => ({
    21→    id: uid(), type: 'component', subtype: 'button', label: `버튼[${label}]`,
    22→    inputs: [{ name: 'props', portType: 'data' }, { name: 'onClick', portType: 'logic' }],
    23→    outputs: [{ name: 'element', portType: 'component' }],
    24→    props: { label, variant },
    25→  }),
    26→
    27→  text: (content = '텍스트', tag = 'p') => ({
    28→    id: uid(), type: 'component', subtype: 'text', label: `텍스트[${content.slice(0,8)}]`,
    29→    inputs: [{ name: 'content', portType: 'data' }],
    30→    outputs: [{ name: 'element', portType: 'component' }],
    31→    props: { content, tag },
    32→  }),
    33→
    34→  input: (placeholder = '입력', type = 'text') => ({
    35→    id: uid(), type: 'component', subtype: 'input', label: `입력[${placeholder}]`,
    36→    inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
    37→    outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
    38→    props: { placeholder, type },
    39→  }),
    40→
    41→  card: (title = '카드') => ({
    42→    id: uid(), type: 'component', subtype: 'card', label: `카드[${title}]`,
    43→    inputs: [{ name: 'title', portType: 'data' }, { name: 'children', portType: 'component' }],
    44→    outputs: [{ name: 'element', portType: 'component' }],
