   575→// ─── 레이아웃 엔진 ────────────────────────────────────────────────
   576→
   577→class LayoutEngine {
   578→  /**
   579→   * 노드 목록 + 엣지 → 위치 자동 계산
   580→   * 레이어 기반 배치: 데이터 → 로직 → 컴포넌트 순
   581→   */
   582→  layout(nodes, edges, offsetX = 100, offsetY = 80) {
   583→    const W = 200, H = 140, GAP_X = 60, GAP_Y = 30;
   584→
   585→    const layers = {
   586→      data:      nodes.filter(n => n.type === 'data'),
   587→      logic:     nodes.filter(n => n.type === 'logic'),
   588→      component: nodes.filter(n => n.type === 'component'),
   589→    };
   590→
   591→    const result = {};
   592→    let baseX = offsetX;
   593→
   594→    for (const [layer, layerNodes] of Object.entries(layers)) {
   595→      if (!layerNodes.length) continue;
   596→
   597→      layerNodes.forEach((n, i) => {
   598→        result[n.id] = {
   599→          x: baseX,
   600→          y: offsetY + i * (H + GAP_Y),
   601→        };
   602→      });
   603→
   604→      baseX += W + GAP_X;
   605→    }
   606→
   607→    return result;
   608→  }
   609→
   610→  /**
   611→   * 기존 노드 위치에서 겹치지 않는 위치 찾기
   612→   */
   613→  findFreePosition(existingPositions, nodeCount) {
   614→    const W = 200, H = 140, GAP = 40;
   615→    const cols = Math.ceil(Math.sqrt(nodeCount));
   616→    const positions = [];
   617→
   618→    for (let i = 0; i < nodeCount; i++) {
   619→      const col = i % cols;
   620→      const row = Math.floor(i / cols);
   621→      const baseX = 600 + col * (W + GAP);
   622→      const baseY = 80 + row * (H + GAP);
   623→      positions.push({ x: baseX, y: baseY });
   624→    }
   625→
   626→    return positions;
   627→  }
   628→}
