/**
 * FreeWire — AI Graph Generator
 *
 * Claude API → 노드 그래프 JSON 동적 생성
 *
 * 사용자의 자연어 설명을 받아서
 * FreeWire 노드 + 와이어 구조를 생성한다.
 *
 * API 키가 없으면 AINodeGenerator(규칙 기반) 폴백으로 동작한다.
 */

'use strict';

let Anthropic;
try {
  Anthropic = require('@anthropic-ai/sdk');
} catch (_) {
  Anthropic = null;
}

const { AINodeGenerator } = require('../ai/node-generator');

