// ─── 메인 함수 ──────────────────────────────────────────────────

/**
 * 자연어 프롬프트 → FreeWire 그래프 JSON 생성
 *
 * @param {string} prompt   - 자연어 UI 설명
 * @param {string} [apiKey] - Claude API 키 (없으면 규칙 기반 폴백)
 * @returns {Promise<object>} { graph, label, nodeCount, edgeCount, source, rawPrompt }
 */
async function aiGenerateGraph(prompt, apiKey) {
  // ── 입력 검증 ────────────────────────────────────────────────
  if (!prompt || typeof prompt !== 'string') {
    throw new Error('prompt는 비어 있지 않은 문자열이어야 합니다');
  }
  const trimmed = prompt.trim();
  if (trimmed.length === 0) {
    throw new Error('prompt는 비어 있지 않은 문자열이어야 합니다');
  }
  if (trimmed.length > 2000) {
    throw new Error('prompt가 너무 깁니다 (최대 2000자)');
  }

  const key = apiKey || process.env.ANTHROPIC_API_KEY;

  // ── API 키 없음 → 규칙 기반 폴백 ─────────────────────────────
  if (!key || !Anthropic) {
    return _fallbackGenerate(trimmed);
  }

  // ── Claude API 호출 ───────────────────────────────────────────
  try {
    const client = new Anthropic({ apiKey: key });

    const message = await client.messages.create({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 2048,
      system: SYSTEM_PROMPT,
      messages: [{ role: 'user', content: trimmed }],
    });

    const raw = message.content[0]?.text ?? '';
    const graph = parseGraphJSON(raw);

    // 레이아웃 계산
    graph.nodes = applyLayout(graph.nodes);

    return {
      graph,
      label:     graph.label,
      nodeCount: graph.nodes.length,
      edgeCount: graph.edges.length,
      source:    'claude-api',
      model:     message.model,
      usage:     message.usage,
      rawPrompt: trimmed,
    };
  } catch (e) {
    // API 실패 시 규칙 기반 폴백
    if (e.message && e.message.includes('API 키')) throw e;  // 인증 오류는 재전파
    const fallback = await _fallbackGenerate(trimmed);
    fallback.fallbackReason = e.message;
    return fallback;
  }
}

// ─── 규칙 기반 폴백 ─────────────────────────────────────────────

async function _fallbackGenerate(prompt) {
  const generator = new AINodeGenerator();
  const result = await generator.generate(prompt);

  // nodes 객체 → 배열로 변환 (parseGraphJSON 포맷과 통일)
  const nodesArray = Object.values(result.nodes ?? {});
  const edgesArray = (result.edges ?? []).map((e, i) => ({
    id:       e.id ?? `e${i + 1}`,
    from:     e.fn ?? e.from,
    fromPort: e.fp ?? e.fromPort ?? 0,
    to:       e.tn ?? e.to,
    toPort:   e.tp ?? e.toPort ?? 0,
  }));

  // 레이아웃 적용
  const nodesWithLayout = applyLayout(nodesArray);

  const graph = {
    label: result.label ?? 'AI 생성 그래프',
    nodes: nodesWithLayout,
    edges: edgesArray,
  };

  return {
    graph,
    label:     graph.label,
    nodeCount: nodesWithLayout.length,
    edgeCount: edgesArray.length,
    source:    'rule-based-fallback',
    intent:    result.intent,
    rawPrompt: prompt,
  };
}

