/**
 * FreeWire Phase 10 Tests
 * Claude API 연동 + 규칙 기반 폴백 시스템
 *
 * 총 25개 테스트
 *
 * 테스트 범위:
 *  - API 키 없을 때 폴백 동작 (규칙 기반)
 *  - prompt 유효성 검사
 *  - 응답 구조 검증 (nodes / edges / label / source)
 *  - JSON 파싱 (parseGraphJSON 내부 동작 포함)
 *  - 레이아웃 자동 계산
 *  - 에러 처리
 */

'use strict';

// ─── 테스트 유틸 ──────────────────────────────────────────────

let passed = 0, failed = 0;

function test(name, fn) {
  try {
    const ret = fn();
    if (ret && typeof ret.then === 'function') {
      // 비동기 테스트 — 이 함수는 Promise를 수집하지 않으므로
      // 모든 async 테스트는 asyncTest() 사용
      throw new Error('비동기 테스트는 asyncTest()를 사용하세요');
    }
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e) {
    console.error(`  ✗ ${name}`);
    console.error(`    → ${e.message}`);
    failed++;
  }
}

async function asyncTest(name, fn) {
  try {
    await fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e) {
    console.error(`  ✗ ${name}`);
    console.error(`    → ${e.message}`);
    failed++;
  }
}

function assert(cond, msg = 'assertion failed') {
  if (!cond) throw new Error(msg);
}

function assertEqual(a, b, msg) {
  if (a !== b)
    throw new Error(msg ?? `expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
}

function assertThrows(fn, msgContains) {
  let threw = false;
  try { fn(); } catch (e) {
    threw = true;
    if (msgContains && !e.message.includes(msgContains)) {
      throw new Error(`에러 메시지에 "${msgContains}" 포함 기대, 실제: "${e.message}"`);
    }
  }
  if (!threw) throw new Error('에러가 발생해야 하는데 발생하지 않음');
}

async function assertRejects(fn, msgContains) {
  let threw = false;
  try { await fn(); } catch (e) {
    threw = true;
    if (msgContains && !e.message.includes(msgContains)) {
      throw new Error(`에러 메시지에 "${msgContains}" 포함 기대, 실제: "${e.message}"`);
    }
  }
  if (!threw) throw new Error('Promise가 reject되어야 하는데 resolve됨');
}

// ─── 모듈 로드 ────────────────────────────────────────────────

const { aiGenerateGraph } = require('../api/ai-graph-generator');

// ─── 유틸 함수 ────────────────────────────────────────────────

function validateGraph(graph, label) {
  assert(graph !== null && typeof graph === 'object', `${label}: graph는 객체`);
  assert(Array.isArray(graph.nodes), `${label}: graph.nodes는 배열`);
  assert(Array.isArray(graph.edges), `${label}: graph.edges는 배열`);
  assert(typeof graph.label === 'string', `${label}: graph.label은 문자열`);
}

function validateResult(result) {
  assert(typeof result === 'object' && result !== null, 'result는 객체');
  assert(typeof result.label === 'string' && result.label.length > 0, 'result.label 필수');
  assert(typeof result.nodeCount === 'number', 'result.nodeCount 필수');
  assert(typeof result.edgeCount === 'number', 'result.edgeCount 필수');
  assert(typeof result.source === 'string', 'result.source 필수');
  assert(typeof result.rawPrompt === 'string', 'result.rawPrompt 필수');
  validateGraph(result.graph, 'result.graph');
}

// ═══════════════════════════════════════════════════════════════
// [Phase 10] Claude API 연동 + 폴백 시스템
// ═══════════════════════════════════════════════════════════════

console.log('\n[Phase 10] Claude API 연동 + 폴백 시스템');

// ── 섹션 1: prompt 유효성 검사 ────────────────────────────────

console.log('\n  [1] prompt 유효성 검사');

async function runValidationTests() {
  await asyncTest('빈 문자열 prompt → 에러', async () => {
    await assertRejects(() => aiGenerateGraph(''), 'prompt는 비어 있지 않은 문자열');
  });

  await asyncTest('공백만 있는 prompt → 에러', async () => {
    await assertRejects(() => aiGenerateGraph('   '), 'prompt는 비어 있지 않은 문자열');
  });

  await asyncTest('null prompt → 에러', async () => {
    await assertRejects(() => aiGenerateGraph(null), 'prompt는 비어 있지 않은 문자열');
  });

  await asyncTest('undefined prompt → 에러', async () => {
    await assertRejects(() => aiGenerateGraph(undefined), 'prompt는 비어 있지 않은 문자열');
  });

  await asyncTest('숫자 prompt → 에러', async () => {
    await assertRejects(() => aiGenerateGraph(123), 'prompt는 비어 있지 않은 문자열');
  });

  await asyncTest('2000자 초과 prompt → 에러', async () => {
    const longPrompt = 'a'.repeat(2001);
    await assertRejects(() => aiGenerateGraph(longPrompt), '너무 깁니다');
  });

  await asyncTest('2000자 딱 맞는 prompt → 통과 (폴백)', async () => {
    const maxPrompt = '로그인' + ' '.repeat(1997);
    const result = await aiGenerateGraph(maxPrompt.trim().padEnd(10, ' ').slice(0, 2000));
    assert(result !== null, '결과가 있어야 함');
  });
}

// ── 섹션 2: 폴백 동작 (API 키 없음) ──────────────────────────

console.log('\n  [2] 규칙 기반 폴백 (API 키 없음)');

async function runFallbackTests() {
  await asyncTest('API 키 없음 → source가 rule-based-fallback', async () => {
    const result = await aiGenerateGraph('로그인 폼', undefined);
    assertEqual(result.source, 'rule-based-fallback');
  });

  await asyncTest('폴백 결과 구조 검증', async () => {
    const result = await aiGenerateGraph('카운터 앱', undefined);
    validateResult(result);
  });

  await asyncTest('폴백 — 로그인 폼 노드 생성', async () => {
    const result = await aiGenerateGraph('로그인', undefined);
    assert(result.nodeCount > 0, '노드가 1개 이상');
    assert(result.edgeCount >= 0, 'edgeCount는 0 이상');
  });

  await asyncTest('폴백 — 카운터 앱 노드 생성', async () => {
    const result = await aiGenerateGraph('카운터 앱 만들어줘', undefined);
    assert(result.nodeCount > 0, '노드가 1개 이상');
    assertEqual(result.source, 'rule-based-fallback');
  });

  await asyncTest('폴백 — 검색 UI 노드 생성', async () => {
    const result = await aiGenerateGraph('검색 UI', undefined);
    assert(result.nodeCount > 0, '노드가 1개 이상');
  });

  await asyncTest('폴백 — 할일 목록 노드 생성', async () => {
    const result = await aiGenerateGraph('todo 리스트', undefined);
    assert(result.nodeCount > 0, '노드가 1개 이상');
    assertEqual(result.source, 'rule-based-fallback');
  });

  await asyncTest('폴백 — rawPrompt가 입력과 일치', async () => {
    const prompt = '대시보드 화면';
    const result = await aiGenerateGraph(prompt, undefined);
    assertEqual(result.rawPrompt, prompt);
  });

  await asyncTest('폴백 — label이 문자열', async () => {
    const result = await aiGenerateGraph('네비게이션 바', undefined);
    assert(typeof result.label === 'string' && result.label.length > 0, 'label 비어 있지 않음');
  });
}

// ── 섹션 3: 그래프 구조 검증 ─────────────────────────────────

console.log('\n  [3] 그래프 구조 검증');

async function runStructureTests() {
  await asyncTest('graph.nodes 배열 타입', async () => {
    const result = await aiGenerateGraph('로그인 폼', undefined);
    assert(Array.isArray(result.graph.nodes), 'graph.nodes는 배열');
  });

  await asyncTest('graph.edges 배열 타입', async () => {
    const result = await aiGenerateGraph('카운터', undefined);
    assert(Array.isArray(result.graph.edges), 'graph.edges는 배열');
  });

  await asyncTest('graph.label 문자열 타입', async () => {
    const result = await aiGenerateGraph('검색', undefined);
    assert(typeof result.graph.label === 'string', 'graph.label은 문자열');
  });

  await asyncTest('nodeCount와 graph.nodes.length 일치', async () => {
    const result = await aiGenerateGraph('로그인', undefined);
    assertEqual(result.nodeCount, result.graph.nodes.length, 'nodeCount 정확성');
  });

  await asyncTest('edgeCount와 graph.edges.length 일치', async () => {
    const result = await aiGenerateGraph('카운터 앱', undefined);
    assertEqual(result.edgeCount, result.graph.edges.length, 'edgeCount 정확성');
  });

  await asyncTest('각 엣지에 from/to 필드 존재', async () => {
    const result = await aiGenerateGraph('로그인', undefined);
    for (const edge of result.graph.edges) {
      assert('from' in edge || 'fn' in edge, `edge.from 필수: ${JSON.stringify(edge)}`);
      assert('to' in edge || 'tn' in edge, `edge.to 필수: ${JSON.stringify(edge)}`);
    }
  });

  await asyncTest('각 노드에 id 필드 존재', async () => {
    const result = await aiGenerateGraph('버튼', undefined);
    for (const node of result.graph.nodes) {
      assert(typeof node.id === 'string' && node.id.length > 0, `node.id 필수: ${JSON.stringify(node)}`);
    }
  });

  await asyncTest('각 노드에 type 필드 존재', async () => {
    const result = await aiGenerateGraph('검색', undefined);
    const validTypes = ['component', 'data', 'logic'];
    for (const node of result.graph.nodes) {
      assert(validTypes.includes(node.type), `node.type이 유효해야 함: ${node.type}`);
    }
  });

  await asyncTest('레이아웃 — 노드에 position 필드 존재', async () => {
    const result = await aiGenerateGraph('로그인', undefined);
    for (const node of result.graph.nodes) {
      assert(node.position && typeof node.position.x === 'number', `position.x 필수: ${node.id}`);
      assert(node.position && typeof node.position.y === 'number', `position.y 필수: ${node.id}`);
    }
  });
}

// ── 섹션 4: 다양한 시나리오 ──────────────────────────────────

console.log('\n  [4] 다양한 시나리오');

async function runScenarioTests() {
  await asyncTest('회원가입 폼 시나리오', async () => {
    const result = await aiGenerateGraph('회원가입 폼 만들어줘', undefined);
    validateResult(result);
    assert(result.nodeCount > 0);
  });

  await asyncTest('결제 폼 시나리오', async () => {
    const result = await aiGenerateGraph('결제 폼', undefined);
    validateResult(result);
  });

  await asyncTest('모달 팝업 시나리오', async () => {
    const result = await aiGenerateGraph('모달 팝업', undefined);
    validateResult(result);
  });

  await asyncTest('한국어+영어 혼용 prompt 처리', async () => {
    const result = await aiGenerateGraph('login form 만들어줘', undefined);
    validateResult(result);
  });

  await asyncTest('빈 문자열 아닌 알 수 없는 prompt → 폴백 생성', async () => {
    const result = await aiGenerateGraph('알 수 없는 이상한 요청 xyz', undefined);
    validateResult(result);
    assertEqual(result.source, 'rule-based-fallback');
  });
}

// ── 메인 실행 ────────────────────────────────────────────────

async function main() {
  await runValidationTests();
  await runFallbackTests();
  await runStructureTests();
  await runScenarioTests();

  console.log(`\n결과: ${passed} passed, ${failed} failed / ${passed + failed} total`);
  if (failed > 0) process.exit(1);
}

main().catch(e => {
  console.error('\n테스트 실행 중 예외:', e);
  process.exit(1);
});
